[{"title": "Multitalk Radio Calanda", "nummer": "04", "kurz": "Gestaltung und Betreuung einer eigenen Radiosendung, live und als Podcast.", "rolle": "Sendung und Gestaltung", "mit": "mit zwei Kolleginnen", "einl": "Multitalk ist eine gemeinsam mit zwei Kolleginnen entwickelte Radiosendung auf Radio Calanda, die alle zwei Wochen live ausgestrahlt und anschliessend als Podcast veröffentlicht wird. Das Gesprächsformat arbeitet mit wechselnden Oberthemen, zu denen jede Moderatorin eine eigene Rubrik einbringt. So entstehen unterschiedliche Perspektiven und inhaltliche Schwerpunkte innerhalb einer Sendung.\n\nDas Projekt entstand im Rahmen des Studiums und vermittelte mir einen praxisnahen Einblick in die Konzeption, Umsetzung und Kommunikation eines Audioformats im Live-Radio-Kontext.", "aufg": ["Gestaltung des visuellen Auftritts (Logo, Bildmaterial)", "Produktion von Fotos und Grafiken für Website und Social Media", "Betreuung und Planung der Social-Media-Inhalte", "Mitarbeit bei Themenfindung und Sendungsvorbereitung"], "links": [{"titel": "Radio Calanda", "url": "https://radiocalanda.ch"}, {"titel": "Beitrag auf Digezz", "url": "https://www.digezz.ch/multitalk-uf-radio-calanda/"}], "karten": [], "pt": "", "ps": []}, {"title": "Soziale Fachdienste", "nummer": "05", "kurz": "Neues Erscheinungsbild und neuer Web-Auftritt für die Soziale Fachdienste AG.", "rolle": "Redesign", "mit": "", "einl": "Für die Sozialen Fachdienste AG habe ich ein Redesign der bestehenden Website entwickelt und umgesetzt. Ziel war es, die Inhalte klarer zu strukturieren, die Orientierung zu verbessern und einen ruhigen, zeitgemässen Auftritt zu schaffen. Der Fokus lag auf guter Lesbarkeit, einer verständlichen Navigation und einer Gestaltung, die den sensiblen Themenbereich unterstützt, ohne sich in den Vordergrund zu drängen.", "aufg": ["Konzeption und Gestaltung des visuellen Redesigns", "Überarbeitung von Struktur, Navigation und Seitenaufbau", "Gestaltung von Layout, Typografie und Farbwelt", "Umsetzung des Designs für die Website"], "links": [{"titel": "Website ansehen", "url": "https://www.sozialefachdienste.ch"}], "karten": [], "pt": "Zuerst entstanden drei Moodboards mit unterschiedlichen Richtungen:", "ps": ["Idee 1: Die Homepage ist je nach Standort grün oder blau. Wählt man den anderen Standort, wechselt sie die Farbe.", "Idee 2: Die Homepage ist farbig und frech, mit Illustrationen, und fällt dadurch auf.", "Idee 3: Die Homepage ist sehr minimalistisch, mit zurückhaltendem Grün und Blau. Für die Standorte gibt es eine Illustration der Skyline."]}, {"title": "FHGR Merch", "nummer": "06", "kurz": "Rebranding und Kollektion in drei Designlinien: Calanda, Typo und Steinbock.", "rolle": "Rebranding", "mit": "", "einl": "Für das FHGR-Merch haben wir ein Rebranding entwickelt, das die visuelle Identität der Hochschule modern und tragbar aufgreift. Ziel war es, eine Kollektion zu gestalten, die von Studierenden gerne getragen wird und gleichzeitig die FHGR authentisch repräsentiert.", "aufg": ["Konzeption und Entwicklung des Rebrandings", "Erstellung von Moodboards, Skizzen und digitalen Mockups", "Gestaltung von Layouts, Typografie und Farbwelten", "Umsetzung und Präsentation der Designs für die Merch-Kollektion"], "links": [{"titel": "Beitrag auf Digezz", "url": "https://www.digezz.ch/fhgr-merch-rebranding-snow-mountains-and-deadlines/"}], "karten": [{"title": "Calanda", "text": "Bezug zur Region mit minimalistischen Höhenlinien und neutralen Farben, ergänzt durch den Claim «snow, mountains and deadlines»."}, {"title": "Typo", "text": "Typografische Experimente mit Logo-Elementen, auffällige, aber klare Farbkombinationen und typografische Inszenierung des Claims."}, {"title": "Steinbock", "text": "Stilisiertes Wappentier, grafisch abstrahiert, jung und verspielt, kombiniert mit auffälligen Farben und einem lässigen Look."}], "pt": "Ausgehend vom Feedback der Studierenden entstanden drei Designlinien. In vier Schritten bis zur Kollektion:", "ps": ["Moodboards pro Designlinie", "Skizzen der Motive", "Digitale Mockups auf Hoodies", "Präsentation der Kollektion"]}, {"title": "Webdesign & Informatik", "nummer": "07", "kurz": "Webdesign von der Idee in Figma bis zur Umsetzung mit HTML, CSS und JavaScript.", "rolle": "Design und Umsetzung", "mit": "Alohameter und Conversations im Team", "einl": "Im Rahmen des Moduls Informatik habe ich mehrere Websites gestaltet und umgesetzt. Der Fokus lag auf Benutzerfreundlichkeit, klarer Struktur und ansprechender visueller Gestaltung.\n\nDie Websites Alohameter und Conversations entstanden im Team. Wir entwickelten zunächst das UX-Design auf Figma, um Benutzerfluss, Navigation und Layouts zu planen, und setzten die Designs danach in Visual Studio Code mit HTML, CSS und JavaScript um. Während des Projekts testeten wir die Interfaces, integrierten Feedback und optimierten kontinuierlich die Benutzererfahrung.\n\nFür das Projekt Whisk & Bliss übernahm ich die Gestaltung vollständig eigenständig. Das UX- und UI-Design entstand komplett auf Figma, inklusive Wireframes, interaktiver Prototypen und visueller Gestaltung. Das Projekt befindet sich aktuell noch in der Designphase.", "aufg": ["UX- und UI-Konzeption auf Figma, inklusive Wireframes und Prototyping", "Gestaltung von Layouts, Typografie, Farbwelt und visuellen Elementen", "Umsetzung der Designs in HTML, CSS und JavaScript (Alohameter und Conversations)", "Testing, Feedbackintegration und kontinuierliche Optimierung", "Zusammenarbeit bei Designentscheidungen und Projektkoordination"], "links": [{"titel": "Alohameter", "url": "https://alohameter.melinagast.ch"}, {"titel": "Conversations", "url": "https://conversations.melinagast.ch"}], "karten": [{"title": "Alohameter", "text": "Live-Daten zu Temperatur und Windgeschwindigkeit rund um die hawaiianischen Inseln Kauai, Oahu, Maui und Big Island. Mit Klick auf die Boje gibt es mehr Informationen."}, {"title": "Conversations", "text": "Eine Website für Deeptalks, mit Fragen wie «who’s most likely to lose their phone for a day?»."}, {"title": "Whisk & Bliss", "text": "Eigenständiges UX- und UI-Design in Figma, aktuell in der Designphase."}], "pt": "", "ps": []}, {"title": "Dokumentarfilme", "nummer": "08", "kurz": "Projektleitung, Gespräche mit Protagonistinnen und Dramaturgie bei Dokumentarfilmen.", "rolle": "Projektleitung", "mit": "im Team", "einl": "Im Rahmen des Studiums habe ich an zwei dokumentarischen Filmprojekten mitgearbeitet: einem Kurzfilm (ca. 5 Minuten) sowie dem 15-minütigen Dokumentarfilm «Queer durch Berlin».\n\nDer Dokumentarfilm verbindet persönliche Erfahrungen queerer Menschen mit historischen Einordnungen und der heutigen queeren Szene Berlins. Gedreht wurde vor Ort in Berlin, unter anderem mit Protagonist:innen aus der Drag-Szene und im Schwulen Museum.\n\nDie Projekte umfassten den gesamten Produktionsprozess von der Konzeption über die Dreharbeiten bis zur Postproduktion. Die Arbeit im Team war klar strukturiert, gleichzeitig verlangten kurzfristige Änderungen, Absagen und technische Herausforderungen viel Flexibilität und Organisation.\n\nDie Filmprojekte haben mir gezeigt, wie entscheidend gute Vorbereitung, klare Rollen und sauberes Datenmanagement für dokumentarisches Arbeiten sind.", "aufg": ["Projektleitung und Terminkoordination", "Kommunikation mit Protagonist:innen und Locations", "Transkription der Interviews für den Schnitt", "Mitwirkung an inhaltlicher Struktur und Dramaturgie"], "links": [{"titel": "Film 1 ansehen", "url": "https://www.youtube.com/watch?v=YigXu5l9y-MI"}, {"titel": "Film 2 ansehen", "url": "https://www.youtube.com/watch?v=_bQ9u-9dyQnw"}], "karten": [], "pt": "", "ps": []}, {"title": "Sketch & Draw", "nummer": "09", "kurz": "Analoge Zeichnungen mit Fokus auf Perspektive, Licht und Schatten.", "rolle": "Zeichnungen", "mit": "", "einl": "Im Rahmen des Moduls Sketch & Draw 1 entstand ein kaleidoskopisches Polyptychon zum Thema «Skizzen des Alltäglichen – der Weg eines Handschuhs». Die Arbeit erzählt in mehreren Bildern die Geschichte eines Handschuhs und folgt ihm durch unterschiedliche alltägliche Situationen und Räume.\n\nGearbeitet wurde analog mit Bleistift auf A4-Papier. Die Zeichnungen fokussieren sich auf Form, Perspektive sowie Licht und Schatten. Unterschiedliche Einstellungsgrössen, Perspektiven und Bildausschnitte strukturieren die Erzählung. Leerraum, Überlagerungen über den Blattrand hinweg sowie variierende Bildgrössen wurden gezielt als Gestaltungselemente eingesetzt.\n\nDie Komposition erstreckt sich über mehrere Seiten im Landscape-Format und bildet eine zusammenhängende visuelle Abfolge aus Detailansichten, räumlichen Situationen und Bewegung.", "aufg": ["Entwicklung der Bildidee und narrativen Abfolge", "Fotografische Vorstudie und kompositorische Planung", "Analoge Zeichnungen mit Fokus auf Perspektive, Licht und Schatten"], "links": [], "karten": [], "pt": "", "ps": []}, {"title": "Konzept RaBe", "nummer": "10", "kurz": "Kommunikationskonzept mit Branding und Web-Auftritt zum 30-Jahr-Jubiläum von Radio Bern RaBe.", "rolle": "Konzept und Design", "mit": "im Team", "einl": "Im Rahmen des Moduls «Schreiben und Sprechen III» haben wir ein Kommunikationskonzept für RaBe entwickelt. Ziel war es, Kommunikationsziele zu definieren und konkrete Massnahmen umzusetzen, die sowohl inhaltlich als auch visuell überzeugen.\n\nNeben der Analyse der bestehenden Kommunikation, der Entwicklung von Zielgruppenprofilen und der Formulierung von Kernbotschaften haben wir einen grossen Teil des Designs übernommen. Dazu gehörten Flyer, Flaggen, Website-Mockups und weitere visuelle Elemente. Wir arbeiteten iterativ, erstellten Moodboards und Mockups, testeten Varianten und passten diese nach Feedback an, um ein stimmiges und konsistentes visuelles Konzept zu entwickeln.", "aufg": ["Mitarbeit bei Recherche, Analyse und Strategieentwicklung", "Mitgestaltung von Kernbotschaften und Kommunikationsplan", "Design und visuelle Umsetzung von Flyern, Flaggen und Website-Mockups", "Erstellung des finalen Konzepts als Dokumentation"], "links": [], "karten": [{"title": "Jubiläumsprogramm", "text": "Podcast-Serie «30 Jahre, 30 Stimmen», Social-Media-Challenge #klingtnachmir, Creator-Takeovers auf Instagram und TikTok, Community-Voting «Welche Stimme fehlt noch?» und Einblicke hinter die Kulissen."}, {"title": "Kampagne", "text": "Bernmobil-Kampagne mit Plakaten in Tram und Bus, Flyer an Hochschulen, Cafés und Festivals, Jubiläumsjingle sowie RaBe-Flaggen und City Branding."}, {"title": "Jubiläumsfest", "text": "DJ-Sets, Live-Musik, Open Mic und Live-Radio-Booth am 17. Juni 2026, Sulgenrain 28, Bern."}], "pt": "Das Konzept stützt sich auf die Werte von RaBe: Das freie Radio versteht sich als Gegenentwurf zu kommerziellem Mainstreamradio. Vielfalt, Kultur und gesellschaftlicher Austausch stehen im Vordergrund, in über 20 Sprachen.", "ps": ["Recherche und Analyse der bestehenden Kommunikation", "Zielgruppenprofile und Kernbotschaften", "Moodboards und Mockups, Varianten testen", "Anpassung nach Feedback und finales Konzept"]}, {"title": "Acne Studios", "nummer": "12", "kurz": "Gestaltungskonzept für einen Shop-in-Shop, mit Renderings und Layoutplänen.", "rolle": "Raumkonzept", "mit": "", "einl": "Während meiner Polydesign-Lehre habe ich ein Gestaltungskonzept für einen Shop-in-Shop von Acne Studios umgesetzt. Ziel war es, die neue Kollektion «New Arrivals» attraktiv zu präsentieren und das Markenimage sichtbar zu machen.\n\nIch habe den gesamten Prozess selbstständig übernommen, von der Analyse der Marke über Materialrecherche, Moodboards, Renderings und Layoutpläne bis hin zur Gestaltung der Ausstellungselemente wie Bodenbelag, Spiegelwände, Deckenraster, Kleiderstangen, Wolkenpodeste, Beleuchtung und Logo-Positionierung. Varianten wurden getestet und iterativ angepasst, um ein stimmiges und konsistentes Konzept zu entwickeln.", "aufg": ["Eigenständige Materialrecherche und Moodboard-Erstellung", "Entwicklung und Umsetzung des Raum- und Farbkonzepts", "Gestaltung der Ausstellungselemente und visuellen Inszenierung", "Erstellung von Renderings, Layoutplänen und finalem Konzeptdossier"], "links": [], "karten": [], "pt": "", "ps": []}]
JSON
, true);
    $log = [];
    foreach ($rows as $r) {
        $found = get_posts(['post_type' => 'project', 'title' => $r['title'], 'numberposts' => 1, 'post_status' => 'any']);
        if (!$found) { $log[] = 'FEHLT (Titel stimmt nicht): ' . $r['title']; continue; }
        $id = $found[0]->ID;
        $list = fn($arr, $key) => array_map(fn($x) => ['_type' => '_', $key => $x], $arr);
        $paras = array_map(fn($p) => '<p>' . esc_html($p) . '</p>', preg_split('/\R{2,}/', trim($r['einl'])));
