        carbon_set_post_meta($id, 'kurzbeschreibung', $r['kurz']);
        carbon_set_post_meta($id, 'rolle', $r['rolle']);
        carbon_set_post_meta($id, 'mitarbeit', $r['mit']);
        carbon_set_post_meta($id, 'einleitung', implode("\n", $paras));
        carbon_set_post_meta($id, 'aufgaben', $list($r['aufg'], 'aufgabe'));
        carbon_set_post_meta($id, 'links', array_map(fn($l) => ['_type' => '_', 'titel' => $l['titel'], 'url' => $l['url']], $r['links']));
        carbon_set_post_meta($id, 'ergebnis_karten', array_map(fn($k) => ['_type' => '_', 'title' => $k['title'], 'text' => $k['text']], $r['karten']));
        carbon_set_post_meta($id, 'prozess_text', $r['pt']);
        carbon_set_post_meta($id, 'prozess_schritte', $list($r['ps'], 'schritt'));
        $log[] = 'Gesetzt: ' . $r['title'] . ' (' . count($r['aufg']) . ' Aufgaben, ' . count($r['links']) . ' Links, ' . count($r['karten']) . ' Karten, ' . count($r['ps']) . ' Schritte)';
    }
    echo implode("\n", $log) . "\n\nFertig. Jetzt diese Datei und die require-Zeile in functions.php entfernen.";
